from app.schemas.ai_analysis import OpportunityAnalysis, Finding, ComplementaryQuestion, RequiredData

def analyze(text: str, notes: str = '') -> OpportunityAnalysis:
    low = text.lower(); freight = any(x in low for x in ['frete','fretes','transport','embarque']); stock = any(x in low for x in ['estoque','inventário','inventario']); wms = 'wms' in low or 'tms' in low
    theme = 'Transportes/Fretes' if freight else 'Estoque/Armazenagem' if stock else 'Diagnóstico logístico'
    problems = [Finding(text='Custos logísticos em crescimento, com foco em fretes.', source_type='CLIENT_REPORT')] if freight else [Finding(text='Problema operacional ainda precisa ser detalhado.', confidence='LOW')]
    questions = []
    if freight:
        freight_questions = [
            ('Financeiro','Qual é o faturamento mensal médio da empresa?'),('Financeiro','Qual é o gasto mensal e anual com fretes?'),('Financeiro','Qual percentual do frete representa sobre o faturamento?'),('Financeiro','Como esse percentual evoluiu nos últimos 6 a 12 meses?'),
            ('Volume','Quantos pedidos são faturados por mês?'),('Volume','Quantos embarques são realizados por mês?'),('Volume','Qual é o ticket médio dos pedidos?'),('Carga','Qual é o peso médio por pedido e por embarque?'),('Carga','Qual é a cubagem média e quantos volumes há por pedido?'),
            ('Geografia','Quais regiões e UFs concentram os embarques?'),('Geografia','Qual é a participação do frete por região atendida?'),('Transportadoras','Quantas transportadoras estão ativas hoje?'),('Transportadoras','Quais são as principais transportadoras e suas participações?'),('Transportadoras','Qual é o critério usado para selecionar cada transportadora?'),
            ('Tarifas','Existem tabelas de frete vigentes por região, faixa de peso ou valor?'),('Tarifas','Quando ocorreram os últimos reajustes e quais índices foram aplicados?'),('Tarifas','São cobradas generalidades, taxas adicionais ou tarifas mínimas?'),('Operação','Há fretes dedicados? Em qual proporção dos embarques?'),('Operação','Existe consolidação de pedidos ou os embarques saem fracionados?'),
            ('Controle','Como é feita a auditoria das faturas de frete?'),('Controle','Qual é o volume de devoluções e reentregas?'),('SLA','Quais são os prazos contratados e realizados por região?'),('SLA','Quais ocorrências ou atrasos geram retrabalho e custo adicional?'),('Dados','Existe histórico detalhado disponível? Em qual formato e período?'),('Dados','O histórico contém pedido, CEP, peso, cubagem, transportadora e valor do frete?')]
        for i, (category, q) in enumerate(freight_questions,1): questions.append(ComplementaryQuestion(id=f'frete-{i}', categoria=category, pergunta=q, obrigatoria=i in (1,2,5,6,10), motivo_interno='Dimensionar custo, perfil de carga, malha, tarifas e nível de serviço.', ordem=i))
    else: questions.append(ComplementaryQuestion(id='geral-1', categoria='Contexto', pergunta='Qual indicador logístico mais preocupa a empresa hoje?', motivo_interno='Definir escopo.', ordem=1))
    hypotheses = [Finding(text=x, confidence='LOW', source_type='INFERENCE') for x in (['Reajustes podem estar impactando o custo total de transporte.','Generalidades e adicionais podem estar elevando o valor final do frete.','Mudança no perfil geográfico pode estar aumentando o percentual de frete.','Peso cubado pode estar impactando o faturamento das transportadoras.','Excesso de fretes dedicados pode elevar o custo médio por embarque.','Baixa consolidação pode aumentar o custo por embarque.','Ausência de comparação sistemática entre transportadoras pode gerar ineficiência.','Ticket médio menor pode elevar o frete sobre faturamento sem aumento equivalente de tarifa.'] if freight else ['A causa do problema ainda precisa ser isolada por dados operacionais.'])]
    required = RequiredData(nome='Histórico detalhado de embarques', descricao='Base transacional para decompor custo, perfil de carga, rota e desempenho.', campos_sugeridos=['data','pedido','valor do pedido','CEP','cidade','UF','peso real','peso cubado','volumes','transportadora','modalidade','valor do frete','prazo contratado','prazo realizado','ocorrência','devolução','reentrega'], periodo_recomendado='6 a 12 meses', formato_preferencial='XLSX ou CSV', origem_sugerida='ERP, TMS ou transportadoras', motivo_interno='Quantificar os direcionadores de custo e testar hipóteses.')
    return OpportunityAnalysis(primary_theme=theme, secondary_themes=['Custos','Fretes','Malha e transportadoras'] if freight else [], central_problem='Custos de transporte em crescimento, sem evidência suficiente para identificar o principal direcionador.' if freight else 'O problema central ainda precisa ser delimitado.', recommended_diagnostic='Diagnóstico de custos de transporte' if freight else 'Diagnóstico logístico exploratório', executive_summary='A oportunidade deve avançar para um diagnóstico orientado por dados, com validação das hipóteses em entrevista e histórico operacional.', reported_facts=[Finding(text='Conteúdo original recebido do cliente foi preservado.', source_type='CLIENT_REPORT')] + ([Finding(text='A operação utiliza transportadoras terceirizadas e não possui TMS.', source_type='CLIENT_REPORT')] if freight else []), consultant_observations=[Finding(text=notes, source_type='CONSULTANT_NOTE')] if notes else [], identified_problems=problems, reported_impacts=[Finding(text='Aumento dos custos logísticos e pressão sobre o resultado operacional.', source_type='CLIENT_REPORT')] if freight else [], hypotheses=hypotheses, information_gaps=[Finding(text=x, confidence='HIGH') for x in (['Não foram informados faturamento, gasto de frete e evolução do percentual.','Não há dados de pedidos, embarques, peso, cubagem e volumes.','Não foram detalhadas regiões, transportadoras, tarifas, adicionais e ocorrências.','Não está confirmado o formato e período do histórico disponível.'] if freight else ['Escopo, indicadores e dados operacionais ainda não foram detalhados.'])], complementary_questions=questions, required_data=[required], suggested_documents=['Tabelas de frete vigentes','Relatórios de frete','Contratos de transportadoras','Relatório de devoluções e reentregas'], suggested_delivery_mode='A_DEFINIR', delivery_mode_reason='Definir após entender dispersão geográfica, qualidade dos dados e necessidade de observação presencial.', pricing_readiness='PARTIAL', implementation_pricing_readiness='NOT_READY', pricing_blockers=['Faltam volume, escopo e dados para estimar horas.'], warnings=['Todas as hipóteses dependem de validação; não representam conclusões.'])
